from __future__ import annotations

import inspect
import json
import re
import sys
import warnings
from pathlib import Path

import numpy as np


TASK_DIR = Path(__file__).resolve().parent
SOURCE = TASK_DIR / "source"
FIXTURE = TASK_DIR / "fixtures" / "public" / "case.json"
OUTPUT = TASK_DIR / "outputs" / "public_reproduction_report.json"


def _write_report(report: dict[str, object], exit_code: int) -> int:
    OUTPUT.parent.mkdir(exist_ok=True)
    OUTPUT.write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    print(json.dumps(report, indent=2, sort_keys=True))
    return exit_code


def _load_case() -> tuple[object, object, set[float], dict[str, object]]:
    sys.path.insert(0, str(SOURCE))
    from nibabel import Nifti1Image
    from nilearn.surface import InMemoryMesh

    case = json.loads(FIXTURE.read_text(encoding="utf-8"))
    shape = tuple(int(value) for value in case["shape"])
    data = np.zeros(shape, dtype=np.float64)
    for index, value in enumerate(case["layer_values"]):
        data[:, :, index] = float(value)
    image = Nifti1Image(data, np.asarray(case["affine"], dtype=float))
    mesh = InMemoryMesh(
        np.asarray(case["mesh_coordinates"], dtype=float),
        np.asarray(case["mesh_faces"], dtype=np.int64),
    )
    table_keys = {float(value) for value in case["table_keys"]}
    return image, mesh, table_keys, case


def _available_behaviors(vol_to_surf: object) -> list[str]:
    """Collect the behaviors exposed by the public callable."""
    doc = inspect.getdoc(vol_to_surf) or ""
    match = re.search(
        r"^interpolation\s*:\s*\{([^}]*)\}", doc, flags=re.MULTILINE
    )
    if match is None:
        return []
    choices = re.findall(r"'([^']+)'|\"([^\"]+)\"", match.group(1))
    return [single or double for single, double in choices]


def _resolves_against_table(values: np.ndarray, table_keys: set[float]) -> bool:
    finite = values[np.isfinite(values)]
    return bool(finite.size) and all(
        float(value) in table_keys for value in finite
    )


def main() -> int:
    try:
        image, mesh, table_keys, case = _load_case()
        from nilearn.surface import vol_to_surf
    except Exception as exc:
        return _write_report(
            {
                "schema_version": "0.1",
                "offline": True,
                "status": "runner_failure",
                "failure_kind": "import_or_fixture_setup",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            1,
        )

    common = {
        "kind": str(case["kind"]),
        "radius": float(case["radius"]),
        "n_samples": int(case["n_samples"]),
    }
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", FutureWarning)
            ordinary = np.asarray(
                vol_to_surf(image, mesh, interpolation="nearest", **common)
            )
    except Exception as exc:
        return _write_report(
            {
                "schema_version": "0.1",
                "offline": True,
                "status": "runner_failure",
                "failure_kind": "ordinary_projection",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            1,
        )

    observed_finite = ordinary[np.isfinite(ordinary)]
    unmatched = [
        value for value in observed_finite if float(value) not in table_keys
    ]
    if not unmatched:
        return _write_report(
            {
                "schema_version": "0.1",
                "offline": True,
                "status": "post_fix_success",
                "failure_kind": None,
                "table_entry_count": len(table_keys),
                "finite_surface_value_count": int(observed_finite.size),
                "unmatched_surface_value_count": 0,
                "resolved_surface_value_count": int(observed_finite.size),
                "all_finite_surface_values_resolve": True,
            },
            0,
        )

    candidate_results: list[np.ndarray] = []
    for behavior in _available_behaviors(vol_to_surf):
        try:
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", FutureWarning)
                candidate_results.append(
                    np.asarray(
                        vol_to_surf(
                            image,
                            mesh,
                            interpolation=behavior,
                            **common,
                        )
                    )
                )
        except Exception:
            continue

    usable_results = [
        result
        for result in candidate_results
        if _resolves_against_table(result, table_keys)
    ]
    if not usable_results:
        return _write_report(
            {
                "schema_version": "0.1",
                "offline": True,
                "status": "pre_fix_expected_failure",
                "failure_kind": "lookup_join_failure",
                "table_entry_count": len(table_keys),
                "finite_surface_value_count": int(observed_finite.size),
                "unmatched_surface_value_count": len(unmatched),
            },
            1,
        )

    repaired = usable_results[0]
    return _write_report(
        {
            "schema_version": "0.1",
            "offline": True,
            "status": "post_fix_success",
            "failure_kind": None,
            "table_entry_count": len(table_keys),
            "finite_surface_value_count": int(observed_finite.size),
            "unmatched_surface_value_count": len(unmatched),
            "resolved_surface_value_count": int(
                repaired[np.isfinite(repaired)].size
            ),
            "all_finite_surface_values_resolve": True,
        },
        0,
    )


if __name__ == "__main__":
    raise SystemExit(main())
